let leaderboardSnapshot=null,leaderboardJob=null;
async function leaderboard(bucket){if(leaderboardSnapshot&&leaderboardSnapshot.until>Date.now())return leaderboardSnapshot.data;if(leaderboardJob)return leaderboardJob;leaderboardJob=(async()=>{let cursor;const candidates=[];do{const page=await bucket.list({prefix:'profiles/',limit:1000,include:['customMetadata'],...(cursor?{cursor}:{})});for(const object of page.objects){const m=object.customMetadata||{};if(m.leaderboard!=='1')continue;const seconds=Number(m.seconds);if(!Number.isSafeInteger(seconds)||seconds<0)continue;const tiers=zeroTiers();for(const key of Object.keys(tiers)){const count=Number(m[key]);tiers[key]=Number.isSafeInteger(count)&&count>=0?count:0}candidates.push({key:object.key,seconds,tiers,total:Object.values(tiers).reduce((a,b)=>a+b,0)})}cursor=page.truncated?page.cursor:null;}while(cursor);candidates.sort((a,b)=>b.seconds-a.seconds||b.total-a.total||a.key.localeCompare(b.key));const users=[];for(const candidate of candidates.slice(0,10)){const object=await bucket.get(candidate.key);if(!object)continue;const p=await object.json();users.push({id:p.id,name:p.name,username:p.username,avatar:p.avatar,seconds:candidate.seconds,tiers:candidate.tiers,total:candidate.total})}const data={users,updatedAt:Date.now()};leaderboardSnapshot={until:Date.now()+15000,data};return data})();try{return await leaderboardJob}finally{leaderboardJob=null}}

export default {async fetch(request,env){try{const url=new URL(request.url);if(url.pathname==='/health'||url.pathname==='/')return json({service:'NEXAVERSE SONY EDITION Community',ready:!!env.BUCKET});if(!env.BUCKET)fail('Community storage is not available.',503);const user=await discordIdentity(request);const parts=url.pathname.split('/').filter(Boolean);


if(url.pathname==='/api/awards'&&request.method==='GET')return json({userId:user.id,games:awardSummaries(user.id)});
if(url.pathname==='/api/admin/apply-kelvin-award'&&request.method==='POST'){if(user.id!=='1548789755892863117')fail('Administrator access required.',403);await persistAwardMetadata(env.BUCKET,'374941137904861185');return json({ok:true,userId:'374941137904861185',games:{'resident-evil-requiem':50,'last-of-us':29},source:'admin'})}
if(url.pathname==='/api/leaderboard'&&request.method==='GET')return json(await leaderboard(env.BUCKET));
if(url.pathname==='/api/steam/playtime'&&request.method==='GET'){if(!env.STEAM_WEB_API_KEY)fail('Steam sync is not configured.',503);const object=await env.BUCKET.get('steam-links/'+user.id+'.json');if(!object)fail('Enable Steam achievement sync to continue.',409);return json(await steamPlaytime((await object.json()).steamId,env.STEAM_WEB_API_KEY))}
if(url.pathname==='/api/steam/status'&&request.method==='GET'){const link=await env.BUCKET.get('steam-links/'+user.id+'.json');return json({configured:!!env.STEAM_WEB_API_KEY,steamId:link?(await link.json()).steamId:null})}
if(url.pathname==='/api/steam/link'&&request.method==='POST'){const body=await bodyJson(request);const steamId=await verifySteam(body.fields,body.returnTo);await env.BUCKET.put('steam-links/'+user.id+'.json',JSON.stringify({steamId,linkedAt:Date.now()}));return json({steamId})}
if(url.pathname==='/api/steam/link'&&request.method==='DELETE'){await env.BUCKET.delete('steam-links/'+user.id+'.json');return json({ok:true})}
if(parts[0]==='api'&&parts[1]==='steam'&&parts[2]==='progress'&&parts.length===4&&request.method==='GET'){if(!Object.hasOwn(steamApps,parts[3]))fail('Steam game is not supported.',404);if(!env.STEAM_WEB_API_KEY)fail('Steam achievement sync is not configured.',503);const link=await env.BUCKET.get('steam-links/'+user.id+'.json');if(!link)fail('Link Steam while Discord is connected to enable achievement sync.',409);const data=await steamGame((await link.json()).steamId,parts[3],env.STEAM_WEB_API_KEY);await recordVerified(env.BUCKET,user.id,parts[3],data);return json(data)}
if(url.pathname==='/api/friends'&&request.method==='PUT'){const body=await bodyJson(request,128000);if(!Array.isArray(body.ids)||body.ids.length>5000||body.ids.some(id=>typeof id!=='string'||!idPattern.test(id)))fail('Invalid friend IDs.',400);const ids=[...new Set(body.ids)].filter(id=>id!==user.id);await env.BUCKET.put('friends/'+user.id+'.json',JSON.stringify({ids,updatedAt:Date.now()}),{httpMetadata:{contentType:'application/json'}});return json({ok:true})}
if(url.pathname==='/api/friends'&&request.method==='DELETE'){await env.BUCKET.delete('friends/'+user.id+'.json');return json({ok:true})}
if(parts[0]==='api'&&parts[1]==='mutual-friends'&&parts.length===3&&idPattern.test(parts[2]||'')&&request.method==='GET'){const target=parts[2];const [a,b]=await Promise.all([env.BUCKET.get('friends/'+user.id+'.json'),env.BUCKET.get('friends/'+target+'.json')]);if(!a||!b)return json({status:'unavailable',ids:[]});const [own,other]=await Promise.all([a.json(),b.json()]);const oldest=Date.now()-30*86400000;if(own.updatedAt<oldest||other.updatedAt<oldest||!own.ids.includes(target)||!other.ids.includes(user.id))return json({status:'unavailable',ids:[]});const theirs=new Set(other.ids);return json({status:'ready',ids:own.ids.filter(id=>id!==user.id&&id!==target&&theirs.has(id))})}
if(url.pathname==='/api/profile'&&request.method==='PUT'){const body=await bodyJson(request);const statuses=['online','away','busy','invisible'];const games=Array.isArray(body.games)?body.games.slice(0,200).filter(g=>typeof g.id==='string'&&/^[a-z0-9-]{1,80}$/.test(g.id)).map(g=>({id:g.id,seconds:Number.isFinite(g.seconds)?Math.max(0,Math.min(1e10,Math.floor(g.seconds))):0,lastPlayed:Number.isFinite(g.lastPlayed)?g.lastPlayed:null})):[];const previous=await profile(env.BUCKET,user.id);const value={id:user.id,name:String(user.global_name||user.username).slice(0,100),username:String(user.username).slice(0,100),avatar:user.avatar?'https://cdn.discordapp.com/avatars/'+user.id+'/'+user.avatar+'.png?size=256':null,about:String(body.about===undefined?previous?.about||'':body.about).slice(0,500),status:statuses.includes(body.status)?body.status:previous?.status||'online',games:[...new Map(games.map(g=>[g.id,g])).values()]};const tiers=await verifiedTotals(env.BUCKET,user.id),seconds=value.games.reduce((total,g)=>total+g.seconds,0);await env.BUCKET.put('profiles/'+user.id+'.json',JSON.stringify(value),{httpMetadata:{contentType:'application/json'},customMetadata:{leaderboard:'1',seconds:String(seconds),...Object.fromEntries(Object.entries(tiers).map(([key,count])=>[key,String(count)]))}});return json({profile:value})}
if(parts[0]==='api'&&parts[1]==='profiles'&&idPattern.test(parts[2]||'')&&parts.length===3&&request.method==='GET')return json({profile:await profile(env.BUCKET,parts[2]),media:await mediaList(env.BUCKET,parts[2]),trophies:await publicTrophyCollection(env.BUCKET,parts[2])});
if(url.pathname==='/api/screenshots'&&request.method==='POST'){if(request.headers.get('Content-Type')!=='image/jpeg')fail('Upload a PNG, JPEG or WebP screenshot through the launcher.',415);if(Number(request.headers.get('Content-Length'))>4000000)fail('Screenshot exceeds the upload limit.',413);const bytes=new Uint8Array(await request.arrayBuffer());if(bytes.length>4000000)fail('Screenshot exceeds the upload limit.',413);if(bytes.length<4||bytes[0]!==255||bytes[1]!==216||bytes[2]!==255)fail('Invalid screenshot image.',415);const existing=await env.BUCKET.list({prefix:'media/'+user.id+'/',limit:51});if(existing.objects.length>=50)fail('You can share up to 50 screenshots.',409);const id=crypto.randomUUID(),createdAt=new Date().toISOString();await env.BUCKET.put('media/'+user.id+'/'+id+'.jpg',bytes,{httpMetadata:{contentType:'image/jpeg'},customMetadata:{createdAt,caption:''}});return json({id,createdAt},201)}
if(parts[0]==='api'&&parts[1]==='media'&&idPattern.test(parts[2]||'')&&mediaPattern.test(parts[3]||'')&&parts.length===4&&request.method==='DELETE'){if(parts[2]!==user.id)fail('You can only remove your own screenshots.',403);await env.BUCKET.delete('media/'+user.id+'/'+parts[3]+'.jpg');return json({ok:true})}
if(parts[0]==='api'&&parts[1]==='media'&&idPattern.test(parts[2]||'')&&mediaPattern.test(parts[3]||'')&&parts.length===4&&request.method==='GET'){const object=await env.BUCKET.get('media/'+parts[2]+'/'+parts[3]+'.jpg');if(!object)fail('Screenshot not found.',404);return new Response(object.body,{headers:{'Content-Type':'image/jpeg','Cache-Control':'private,max-age=60','X-Content-Type-Options':'nosniff'}})}
return json({error:'Not found.'},404)}catch(error){if(!error.status)console.error('community_failure',urlSafeError(error));return json({error:error.status?error.message:'Community service temporarily unavailable.'},error.status||503)}}};
